CREATE COLUMN TABLE "TEST_AP"."OWTM" ("WtmCode" INTEGER CS_INT NOT NULL , "Name" NVARCHAR(20) NOT NULL , "Remarks" NVARCHAR(100), "Conds" NVARCHAR(1) DEFAULT 'N', "Active" NVARCHAR(1) DEFAULT 'Y', "UserSign" SMALLINT CS_INT, "PmptChg" NVARCHAR(1) DEFAULT 'Y', "AppOnUpd" NVARCHAR(1) DEFAULT 'Y', PRIMARY KEY ("WtmCode")) UNLOAD PRIORITY 0  AUTO MERGE ;
CREATE UNIQUE INDEX "OWTM_NAME" ON "TEST_AP"."OWTM" ( "Name" ASC )